package com.witchersbestiary.test;
import com.witchersbestiary.economy.*;import com.witchersbestiary.economy.Currency;import com.witchersbestiary.contracts.*;import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import java.util.*;
public final class WalletTests implements FabricGameTest{
 private void denied(TestContext c,Runnable r){boolean fail=false;try{r.run();}catch(IllegalArgumentException|IllegalStateException|ArithmeticException e){fail=true;}c.assertTrue(fail,"Unsafe transaction rejected");}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void physicalItemsAndSerialization(TestContext c){var w=new ItemStack(Currency.WALLET);w.set(WalletComponents.BALANCE,9000000000000L);var n=w.encode(c.getWorld().getRegistryManager());var copy=ItemStack.fromNbt(c.getWorld().getRegistryManager(),n).orElseThrow();c.assertTrue(WalletTransactions.balance(copy)==9000000000000L&&copy.getMaxCount()==1&&Currency.CROWN.getMaxCount()==64,"Long component and physical stacks roundtrip");c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void atomicDepositWithdrawAndCapacity(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();var w=new ItemStack(Currency.WALLET);p.getInventory().setStack(0,w);p.getInventory().setStack(1,new ItemStack(Currency.CROWN,64));WalletTransactions.transfer(p,w,true,64);c.assertTrue(WalletTransactions.balance(w)==64&&p.getInventory().count(Currency.CROWN)==0,"Deposit");WalletTransactions.transfer(p,w,false,10);c.assertTrue(WalletTransactions.balance(w)==54&&p.getInventory().count(Currency.CROWN)==10,"Withdraw");denied(c,()->WalletTransactions.transfer(p,w,false,55));for(int i=1;i<36;i++)p.getInventory().setStack(i,new ItemStack(Items.STONE,64));denied(c,()->WalletTransactions.transfer(p,w,false,1));c.assertTrue(WalletTransactions.balance(w)==54,"No partial failure");p.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void overflowAndMultipleWallets(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();var a=new ItemStack(Currency.WALLET);var b=new ItemStack(Currency.WALLET);a.set(WalletComponents.BALANCE,Long.MAX_VALUE);p.getInventory().setStack(0,a);p.getInventory().setStack(1,b);p.getInventory().setStack(2,new ItemStack(Currency.CROWN,2));denied(c,()->WalletTransactions.transfer(p,a,true,1));WalletTransactions.transfer(p,b,true,2);c.assertTrue(WalletTransactions.balance(a)==Long.MAX_VALUE&&WalletTransactions.balance(b)==2,"Exact wallet selected");denied(c,()->CrownBalance.withdraw(0,-1));p.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void packetReplayAndMovedWallet(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();var w=new ItemStack(Currency.WALLET);p.getInventory().setStack(0,w);p.getInventory().setStack(1,new ItemStack(Currency.CROWN,20));var h=new WalletHandler(941,p.getInventory(),0);p.currentScreenHandler=h;var a=new WalletPackets.Action(941,0,true,10);h.act(p,a);h.act(p,a);c.assertTrue(WalletTransactions.balance(w)==10&&p.getInventory().count(Currency.CROWN)==10,"Duplicate nonce consumes once");p.getInventory().setStack(0,ItemStack.EMPTY);p.getInventory().setStack(2,w);h.act(p,new WalletPackets.Action(941,1,true,10));c.assertTrue(WalletTransactions.balance(w)==10&&!h.canUse(p),"Movement invalidates bound session");p.currentScreenHandler=p.playerScreenHandler;p.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void pickupOwnerDelayAndFullInventory(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();var w=new ItemStack(Currency.WALLET);p.getInventory().setStack(0,w);for(int i=1;i<36;i++)p.getInventory().setStack(i,new ItemStack(Items.STONE,64));var e=new net.minecraft.entity.ItemEntity(c.getWorld(),p.getX(),p.getY(),p.getZ(),new ItemStack(Currency.CROWN,64));c.getWorld().spawnEntity(e);e.setPickupDelay(20);e.onPlayerCollision(p);c.assertTrue(WalletTransactions.balance(w)==0,"Vanilla pickup delay");e.resetPickupDelay();e.setOwner(UUID.randomUUID());e.onPlayerCollision(p);c.assertTrue(WalletTransactions.balance(w)==0,"Owner gate");e.setOwner(p.getUuid());e.onPlayerCollision(p);c.assertTrue(e.isRemoved()&&WalletTransactions.balance(w)==64,"Pickup into wallet with full inventory exactly once");e.onPlayerCollision(p);c.assertTrue(WalletTransactions.balance(w)==64,"Removed entity never paid twice");p.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a")
 public void legacyEmeraldAndNewCrownRewardPlans(TestContext c){var legacy=new ContractDefinition.Reward(10,List.of(new ContractDefinition.ItemReward(net.minecraft.util.Identifier.of("minecraft:emerald"),3)));var w=new ItemStack(Currency.WALLET);var slots=new ArrayList<ItemStack>(Collections.nCopies(36,ItemStack.EMPTY));slots.set(0,w);var old=ContractRewards.plan(slots,legacy);c.assertTrue(old.stream().anyMatch(s->s.isOf(Items.EMERALD)&&s.getCount()==3)&&WalletTransactions.balance(old.get(0))==0,"Old snapshot retains emeralds");var fresh=new ContractDefinition.Reward(10,List.of(new ContractDefinition.ItemReward(net.minecraft.util.Identifier.of("witchersbestiary:witcher_crown"),200)));var plan=ContractRewards.plan(slots,fresh);c.assertTrue(WalletTransactions.balance(plan.get(0))==200&&WalletTransactions.balance(w)==0,"Reward preflight pure; planned wallet delivery");c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a-lifecycle")
 public void droppedWalletTransfersExactBalance(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();var q=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();q.getInventory().clear();var wallet=new ItemStack(Currency.WALLET);wallet.set(WalletComponents.BALANCE,223344L);p.getInventory().setStack(0,wallet);var entity=p.dropItem(wallet.copy(),false);p.getInventory().setStack(0,ItemStack.EMPTY);entity.resetPickupDelay();entity.onPlayerCollision(q);c.assertTrue(entity.isRemoved()&&WalletTransactions.balance(q.getInventory().getStack(0))==223344L,"Vanilla drop/pickup transfers physical wallet balance");p.discard();q.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a-lifecycle")
 public void deathHonorsKeepInventory(TestContext c){var rules=c.getWorld().getGameRules();boolean old=rules.getBoolean(net.minecraft.world.GameRules.KEEP_INVENTORY);try{for(boolean keep:new boolean[]{true,false}){rules.get(net.minecraft.world.GameRules.KEEP_INVENTORY).set(keep,c.getWorld().getServer());var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();var wallet=new ItemStack(Currency.WALLET);wallet.set(WalletComponents.BALANCE,332211L);p.getInventory().setStack(0,wallet);p.setHealth(0);p.onDeath(c.getWorld().getDamageSources().genericKill());if(keep)c.assertTrue(WalletTransactions.balance(p.getInventory().getStack(0))==332211L,"keepInventory retains wallet");else{c.assertTrue(p.getInventory().getStack(0).isEmpty(),"Death drops wallet");var drops=c.getWorld().getEntitiesByClass(net.minecraft.entity.ItemEntity.class,p.getBoundingBox().expand(8),e->e.getStack().isOf(Currency.WALLET)&&WalletTransactions.balance(e.getStack())==332211L);c.assertTrue(!drops.isEmpty(),"Death drop retains exact component");drops.forEach(net.minecraft.entity.Entity::discard);}p.discard();}}finally{rules.get(net.minecraft.world.GameRules.KEEP_INVENTORY).set(old,c.getWorld().getServer());}c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21a-lifecycle")
 public void legacyClaimAndNewClaimUseDifferentCurrency(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();p.getInventory().setStack(0,new ItemStack(Currency.WALLET));var definition=Contracts.DEFINITIONS.all().values().stream().filter(d->!com.witchersbestiary.contracts.procedural.ProceduralHunts.isDefinition(d.id())&&!d.id().equals(com.witchersbestiary.contracts.hunt.SwampLord.ID)&&!d.id().equals(com.witchersbestiary.contracts.hunt.GraveDevourer.ID)).findFirst().orElseThrow();var legacy=new ContractInstance(UUID.randomUUID(),p.getUuid(),definition,System.currentTimeMillis());legacy.transition(ContractInstance.Status.ACCEPTED);for(int k=0;k<definition.required();k++)legacy.credit(UUID.randomUUID(),p.getUuid(),definition.target(),System.currentTimeMillis());var store=new ContractState();store.add(legacy);var restored=ContractState.read(store.writeNbt(new NbtCompound(),c.getWorld().getRegistryManager()),c.getWorld().getRegistryManager());var saved=restored.find(legacy.id());ContractRewards.claim(restored,saved,p);denied(c,()->ContractRewards.claim(restored,saved,p));c.assertTrue(p.getInventory().count(Items.EMERALD)>0&&WalletTransactions.balance(p.getInventory().getStack(0))==0,"Legacy NBT snapshot pays only emeralds");var fresh=Contracts.assign(p,definition.id());for(int k=0;k<definition.required();k++)fresh.credit(UUID.randomUUID(),p.getUuid(),definition.target(),System.currentTimeMillis());ContractRewards.claim(ContractState.get(p.getServer()),fresh,p);long paid=WalletTransactions.balance(p.getInventory().getStack(0));c.assertTrue(paid>0,"New reward delivered to wallet");denied(c,()->Contracts.claim(p,fresh.id()));c.assertTrue(WalletTransactions.balance(p.getInventory().getStack(0))==paid,"No repeat crown reward");p.discard();c.complete();}
}
